// kittu-compat:file
// Generated by scripts/rebrand-kittu.mjs. Runtime compatibility with installs
// that still use the Cyrus names. The legacy names in this file are intentional
// and are never renamed by the codemod.
import { existsSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";

let legacyHomeNoticeShown = false;

/**
 * Default Kittu home directory: `~/.kittu`. When it does not exist but the
 * legacy `~/.cyrus` does (an install that has not been migrated yet), the
 * legacy directory is used so no state is split between two homes.
 */
export function defaultKittuHome(home: string = homedir()): string {
	const current = join(home, ".kittu");
	const legacy = join(home, ".cyrus");
	if (!existsSync(current) && existsSync(legacy)) {
		if (!legacyHomeNoticeShown) {
			legacyHomeNoticeShown = true;
			process.stderr.write(
				`[kittu] using legacy home ${legacy}; move it to ${current}\n`,
			);
		}
		return legacy;
	}
	return current;
}

export interface HookScriptCandidate {
	file: string;
	platform: "unix" | "windows";
}

/**
 * Repository hook script names for `hook` ("setup" | "teardown"), in
 * preference order: `kittu-<hook>.*` first, then the legacy `cyrus-<hook>.*`
 * so existing repositories keep working.
 */
export function hookScriptCandidates(hook: string): HookScriptCandidate[] {
	const candidates: HookScriptCandidate[] = [];
	for (const prefix of ["kittu", "cyrus"]) {
		candidates.push(
			{ file: `${prefix}-${hook}.sh`, platform: "unix" },
			{ file: `${prefix}-${hook}.ps1`, platform: "windows" },
			{ file: `${prefix}-${hook}.cmd`, platform: "windows" },
			{ file: `${prefix}-${hook}.bat`, platform: "windows" },
		);
	}
	return candidates;
}
